  const registry = new ToolRegistry();
  const seenInputs: Array<Record<string, unknown>> = [];
  registry.register(
    {
      name: 'lookup_city',
      description: 'Look up a city by name',
      inputSchema: {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
    },
    async input => {
      seenInputs.push(input);
      return 'Berlin is cloudy';
    }
  );

  const recordedRequests: SendMessageParams[] = [];
  const scriptedChunks: MessageChunk[][] = [
    [{type: 'tool_use', toolCall: {id: 'c-1', name: 'lookup_city', input: {}}}, STOP_FOR_TOOL],
    [{type: 'tool_use', toolCall: {id: 'c-2', name: 'lookup_city', input: {city: 'Berlin'}}}, STOP_FOR_TOOL],
    [{type: 'text', text: 'Berlin is cloudy'}, STOP_DONE],
  ];
  const provider: AIProvider = {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      const turnChunks = scriptedChunks[recordedRequests.length] ?? [];
      recordedRequests.push(params);
      for (const chunk of turnChunks) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };

  const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
  const finalReply = await orchestrator.processMessage(createSession('How is Berlin?'));
  const secondTurnMessages = recordedRequests[1]?.messages ?? [];
  const toolResultMsg = secondTurnMessages[secondTurnMessages.length - 1] as ToolResultMessage | undefined;
  const rejectionText = toolResultMsg?.content[0]?.content ?? '';

  expect({
    finalReply,
    seenInputs,
    mentionsCity: rejectionText.includes('city'),
    mentionsRequired: /required/i.test(rejectionText),
  }).toEqual({
    finalReply: 'Berlin is cloudy',
    seenInputs: [{city: 'Berlin'}],
    mentionsCity: true,
    mentionsRequired: true,
  });
});

